local base=np.array({{np.complex(0.0,0.0),np.complex(1.0,0.0),np.complex(2.0,0.0),np.complex(3.0,0.0)},{np.complex(4.0,0.0),np.complex(5.0,0.0),np.complex(6.0,0.0),np.complex(7.0,0.0)},{np.complex(8.0,0.0),np.complex(9.0,0.0),np.complex(10.0,0.0),np.complex(11.0,0.0)}},"complex128")
local a=base:get(np.s(),np.s(1,nil,2))
local selector={1,-1,2,3}
local values=np.flip(base,2)
local ok,result=pcall(function() return np.put(a,selector,values,"raise") end)
assert(ok==true,"noncontiguous-values/complex128/strided/True: acceptance")
if ok then assert(result==nil,"noncontiguous-values/complex128/strided/True: return") end
eq(base:tolist(),{{np.complex(3.0,0.0),np.complex(1.0,0.0),np.complex(1.0,0.0),np.complex(3.0,0.0)},{np.complex(0.0,0.0),np.complex(5.0,0.0),np.complex(6.0,0.0),np.complex(7.0,0.0)},{np.complex(8.0,0.0),np.complex(9.0,0.0),np.complex(2.0,0.0),np.complex(11.0,0.0)}},"noncontiguous-values/complex128/strided/True")
eq(a.shape,{3,2},"noncontiguous-values/complex128/strided/True: shape")
eq(a.strides,{64,32},"noncontiguous-values/complex128/strided/True: strides")
cases=cases+1
end
-- 1000: zero-stride/int32; oracle error=None
do
local base=np.array({{0,1,2,3}},"int32")
local a=np.broadcast_arrays(base,np.zeros({3,4}))[1]
local selector={1,5,-1}
local values={7,8}
local ok,result=pcall(function() return np.put(a,selector,values,"raise") end)
assert(ok==true,"zero-stride/int32: acceptance")
if ok then assert(result==nil,"zero-stride/int32: return") end
eq(base:tolist(),{{0,1,2,7}},"zero-stride/int32")
eq(a.shape,{3,4},"zero-stride/int32: shape")
eq(a.strides,{0,4},"zero-stride/int32: strides")
cases=cases+1
end
